-- Run on startup after EnsureCreated. Preserve unassigned single-store records until an operator assigns them.
CREATE TABLE IF NOT EXISTS "Shops" (
 "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, "Slug" text NOT NULL, "Email" text NOT NULL,
 "AdminName" text NOT NULL, "PasswordHash" text NOT NULL, "Name" text NOT NULL, "BrowserTitle" text NOT NULL,
 "Logo" text NOT NULL DEFAULT '', "Banner" text NOT NULL DEFAULT '', "Theme" text NOT NULL DEFAULT 'royal',
 "Status" text NOT NULL DEFAULT 'Pending', "Plan" text NOT NULL DEFAULT '', "ExpiresAt" timestamptz,
 "SessionVersion" bigint NOT NULL DEFAULT 0, "SettingsVersion" bigint NOT NULL DEFAULT 0,
 "CreatedAt" timestamptz NOT NULL DEFAULT now(), "ConfigJson" text NOT NULL
);
CREATE UNIQUE INDEX IF NOT EXISTS shop_email ON "Shops" ("Email");
CREATE UNIQUE INDEX IF NOT EXISTS shop_slug ON "Shops" ("Slug");
ALTER TABLE "Products"
 ADD COLUMN IF NOT EXISTS "ShopId" integer,
 ADD COLUMN IF NOT EXISTS "Version" bigint NOT NULL DEFAULT 0,
 ADD COLUMN IF NOT EXISTS "WeightKg" numeric NOT NULL DEFAULT 0.5,
 ADD COLUMN IF NOT EXISTS "ShippingCharge" numeric NOT NULL DEFAULT 0,
 ADD COLUMN IF NOT EXISTS "PromoLabel" text NOT NULL DEFAULT '',
 ADD COLUMN IF NOT EXISTS "PromoKind" text NOT NULL DEFAULT 'None',
 ADD COLUMN IF NOT EXISTS "PromoValue" numeric NOT NULL DEFAULT 0;
ALTER TABLE "Orders"
 ADD COLUMN IF NOT EXISTS "ShopId" integer,
 ADD COLUMN IF NOT EXISTS "City" text NOT NULL DEFAULT '',
 ADD COLUMN IF NOT EXISTS "RequestId" text NOT NULL DEFAULT '',
 ADD COLUMN IF NOT EXISTS "Booking" text NOT NULL DEFAULT 'Unbooked',
 ADD COLUMN IF NOT EXISTS "Tracking" text NOT NULL DEFAULT '',
 ADD COLUMN IF NOT EXISTS "PaymentReference" text NOT NULL DEFAULT '',
 ADD COLUMN IF NOT EXISTS "PaymentVerified" boolean NOT NULL DEFAULT false,
 ADD COLUMN IF NOT EXISTS "WeightKg" numeric NOT NULL DEFAULT 0,
 ADD COLUMN IF NOT EXISTS "Shipping" numeric NOT NULL DEFAULT 0,
 ADD COLUMN IF NOT EXISTS "Subtotal" numeric NOT NULL DEFAULT 0,
 ADD COLUMN IF NOT EXISTS "Courier" text NOT NULL DEFAULT '';
ALTER TABLE "OrderItems" ADD COLUMN IF NOT EXISTS "ListPrice" numeric NOT NULL DEFAULT 0,
 ADD COLUMN IF NOT EXISTS "PromoLabel" text NOT NULL DEFAULT '', ADD COLUMN IF NOT EXISTS "WeightKg" numeric NOT NULL DEFAULT 0;
UPDATE "Orders" SET "Subtotal"="Total" WHERE "ShopId" IS NULL AND "Subtotal"=0;
UPDATE "OrderItems" SET "ListPrice"="UnitPrice" WHERE "ListPrice"=0 AND "UnitPrice">0;
CREATE INDEX IF NOT EXISTS product_store ON "Products" ("ShopId");
CREATE INDEX IF NOT EXISTS order_store ON "Orders" ("ShopId","CreatedAt");
CREATE UNIQUE INDEX IF NOT EXISTS order_request ON "Orders" ("ShopId","RequestId") WHERE "RequestId"<>'';
ALTER TABLE "Orders" ADD COLUMN IF NOT EXISTS "IsCod" boolean NOT NULL DEFAULT true,
 ADD COLUMN IF NOT EXISTS "BookingStarted" timestamptz;
DO $migration$
BEGIN
 IF NOT EXISTS (SELECT FROM pg_constraint WHERE conrelid='"Products"'::regclass AND conname='product_store_fk') THEN
  ALTER TABLE "Products" ADD CONSTRAINT product_store_fk FOREIGN KEY ("ShopId") REFERENCES "Shops" ("Id");
 END IF;
 IF NOT EXISTS (SELECT FROM pg_constraint WHERE conrelid='"Orders"'::regclass AND conname='order_store_fk') THEN
  ALTER TABLE "Orders" ADD CONSTRAINT order_store_fk FOREIGN KEY ("ShopId") REFERENCES "Shops" ("Id");
 END IF;
END
$migration$;
ALTER TABLE "Products" ADD COLUMN IF NOT EXISTS "Details" text NOT NULL DEFAULT '',
 ADD COLUMN IF NOT EXISTS "Gallery" text[] NOT NULL DEFAULT ARRAY[]::text[];
ALTER TABLE "Shops" ADD COLUMN IF NOT EXISTS "PostExSecret" text NOT NULL DEFAULT '';
ALTER TABLE "Shops" ADD COLUMN IF NOT EXISTS "PromoVideo" text NOT NULL DEFAULT '',
 ADD COLUMN IF NOT EXISTS "SocialLinksJson" text NOT NULL DEFAULT '[]';
ALTER TABLE "Shops" ADD COLUMN IF NOT EXISTS "BannerSlides" text[] NOT NULL DEFAULT ARRAY[]::text[],
 ADD COLUMN IF NOT EXISTS "LocalizationJson" text NOT NULL DEFAULT '';
